operations.reducer:
if (!action.input.name.trim())
  throw new InvalidUnitError("A unit needs a name");
if (state.units.some((u) => u.id === action.input.id))
  throw new DuplicateIdError("Unit id already exists");
state.units.push({
  id: action.input.id,
  name: action.input.name,
  level: action.input.level,
  symbols: [],
  rooms: [],
  background: null,
});

const u = state.units.find((x) => x.id === action.input.id);
if (!u) throw new UnknownUnitError("Unknown unit");
if (!action.input.name.trim())
  throw new InvalidUnitError("A unit needs a name");
u.name = action.input.name;

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const r = action.input.room;
if (!r.name.trim()) throw new InvalidRoomError("A room needs a name");
if (r.points.length < 3) throw new InvalidRoomError("A room needs at least three points");
u.rooms = u.rooms ?? [];
if (u.rooms.some((x) => x.id === r.id)) throw new DuplicateIdError("Room id already exists");
u.rooms.push({
  id: r.id,
  name: r.name.trim(),
  points: r.points.map((point) => ({ x: point.x, y: point.y })),
  fillColor: r.fillColor ?? null,
  labelX: r.labelX,
  labelY: r.labelY,
  locked: r.locked ?? null,
});

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const r = (u.rooms ?? []).find((x) => x.id === action.input.id);
if (!r) throw new UnknownRoomError("Unknown room");
const i = action.input;
if (i.name != null) {
  if (!i.name.trim()) throw new InvalidRoomError("A room needs a name");
  r.name = i.name.trim();
}
if (i.fillColor !== undefined) r.fillColor = i.fillColor;
if (i.points != null) r.points = i.points.map((point) => ({ x: point.x, y: point.y }));
if (i.labelX !== undefined && i.labelX !== null) r.labelX = i.labelX;
if (i.labelY !== undefined && i.labelY !== null) r.labelY = i.labelY;
if (i.locked !== undefined) r.locked = i.locked;

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
if (!(u.rooms ?? []).some((x) => x.id === action.input.id)) throw new UnknownRoomError("Unknown room");
u.rooms = (u.rooms ?? []).filter((x) => x.id !== action.input.id);
for (const s of u.symbols) if (s.roomId === action.input.id) s.roomId = null;

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
if (
  state.units.some((x) =>
    x.symbols.some((s) => s.id === action.input.symbol.id),
  )
)
  throw new DuplicateIdError("Symbol id already exists");
const symbol = action.input.symbol;
u.symbols.push({
  ...symbol,
  circuitId: symbol.circuitId ?? null,
  color: symbol.color ?? null,
  label: symbol.label ?? null,
  locked: symbol.locked ?? null,
  mountHeightCm: symbol.mountHeightCm ?? null,
  roomId: symbol.roomId ?? null,
  details: null,
  knx: symbol.knxEnabled ? { enabled: true, groupAddressIds: [], participantName: null } : null,
});

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const s = u.symbols.find((x) => x.id === action.input.id);
if (!s) throw new UnknownSymbolError("Unknown symbol");
const i = action.input;
if (i.defId !== undefined && i.defId !== null) s.defId = i.defId;
if (i.circuitId !== undefined) s.circuitId = i.circuitId;
if (i.roomId !== undefined) s.roomId = i.roomId;
if (i.label !== undefined) s.label = i.label;
if (i.color !== undefined) s.color = i.color;
if (i.rotation !== undefined && i.rotation !== null)
  s.rotation = i.rotation;
if (i.mountHeightCm !== undefined) s.mountHeightCm = i.mountHeightCm;
if (i.locked !== undefined && i.locked !== null) s.locked = i.locked;
if (i.knxEnabled !== undefined && i.knxEnabled !== null) {
  s.knx = {
    enabled: i.knxEnabled,
    groupAddressIds: i.knxEnabled ? (s.knx?.groupAddressIds ?? []) : [],
    participantName: s.knx?.participantName ?? null,
  };
  if (!i.knxEnabled)
    state.groupAddresses = state.groupAddresses.filter(
      (address) => address.fixtureId !== s.id,
    );
}

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const s = u.symbols.find((x) => x.id === action.input.id);
if (!s) throw new UnknownSymbolError("Unknown symbol");
const i = action.input;
s.details = {
  photos: s.details?.photos ?? null,
  price: i.price !== undefined ? i.price : (s.details?.price ?? null),
  note: i.note !== undefined ? i.note : (s.details?.note ?? null),
};

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const s = u.symbols.find((x) => x.id === action.input.id);
if (!s) throw new UnknownSymbolError("Unknown symbol");
s.position = { x: action.input.x, y: action.input.y };

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
u.symbols = u.symbols.filter((s) => s.id !== action.input.id);
state.groupAddresses = state.groupAddresses.filter(
  (ga) => ga.fixtureId !== action.input.id,
);

if (!action.input.name.trim())
  throw new InvalidUnitError("A project needs a name");
state.name = action.input.name;

if (!state.units.some((u) => u.id === action.input.unitId))
  throw new UnknownUnitError("Unknown unit");
state.activeUnitId = action.input.unitId;

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const background = action.input.background;
u.background = background
  ? {
      dataUrl: background.dataUrl ?? null,
      widthCm: background.widthCm ?? null,
      heightCm: background.heightCm ?? null,
      x: background.x,
      y: background.y,
      scale: background.scale,
      opacity: background.opacity,
      rotation: background.rotation,
      locked: background.locked,
    }
  : null;

const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
if (!u.background)
  u.background = {
    dataUrl: null,
    widthCm: null,
    heightCm: null,
    x: 0,
    y: 0,
    scale: 1,
    opacity: 0.5,
    rotation: 0,
    locked: false,
  };
const i = action.input;
const b = u.background;
if (i.dataUrl !== undefined) b.dataUrl = i.dataUrl;
if (i.widthCm !== undefined) b.widthCm = i.widthCm;
if (i.heightCm !== undefined) b.heightCm = i.heightCm;
if (i.x != null) b.x = i.x;
if (i.y != null) b.y = i.y;
if (i.scale != null) b.scale = i.scale;
if (i.opacity != null) b.opacity = i.opacity;
if (i.rotation != null) b.rotation = i.rotation;
if (i.locked != null) b.locked = i.locked;

const s = action.input.settings;
if (s.symbolStyle != null) state.settings.symbolStyle = s.symbolStyle;
if (s.showCircuitBadges != null) state.settings.showCircuitBadges = s.showCircuitBadges;
if (s.showMountHeights != null) state.settings.showMountHeights = s.showMountHeights;

if (state.circuits.some((c) => c.id === action.input.circuit.id))
  throw new DuplicateIdError("Circuit id already exists");
if (
  state.circuits.some((c) => c.skNumber === action.input.circuit.skNumber)
)
  throw new DuplicateCircuitNumberError("Circuit number already exists");
const c = action.input.circuit;
state.circuits.push({
  id: c.id,
  skNumber: c.skNumber,
  name: c.name,
  kind: c.kind,
  distributorId: c.distributorId ?? null,
  color: c.color ?? null,
  notes: c.notes ?? null,
  phases: c.phases ?? null,
  breaker: {
    characteristic: c.breaker.characteristic,
    poles: c.breaker.poles,
    ratingA: c.breaker.ratingA,
    rcbo: c.breaker.rcbo ?? false,
    rcdMa: c.breaker.rcdMa ?? null,
  },
  cable: {
    type: c.cable.type,
    crossSectionMm2: c.cable.crossSectionMm2,
    lengthM: c.cable.lengthM ?? null,
  },
  installationMethod: c.installationMethod ?? "B2",
  ambientTempC: c.ambientTempC ?? 30,
  groupedCircuits: c.groupedCircuits ?? 1,
});
state.nextCircuitNumber = Math.max(
  state.nextCircuitNumber,
  c.skNumber + 1,
);

const c = state.circuits.find((x) => x.id === action.input.id);
if (!c) throw new UnknownCircuitError("Unknown circuit");
const i = action.input;
if (i.name != null) c.name = i.name;
if (i.kind != null) c.kind = i.kind;
if (i.color !== undefined) c.color = i.color;
if (i.phases !== undefined) c.phases = i.phases;
if (i.rcbo !== undefined && i.rcbo !== null) c.breaker.rcbo = i.rcbo;
if (i.distributorId !== undefined) c.distributorId = i.distributorId;
if (i.ratingA != null) c.breaker.ratingA = i.ratingA;
if (i.characteristic != null)
  c.breaker.characteristic = i.characteristic;
if (i.poles != null) c.breaker.poles = i.poles;
if (i.rcdMa !== undefined) c.breaker.rcdMa = i.rcdMa;
if (i.cableType != null) c.cable.type = i.cableType;
if (i.crossSectionMm2 != null)
  c.cable.crossSectionMm2 = i.crossSectionMm2;
if (i.lengthM !== undefined) c.cable.lengthM = i.lengthM;
if (i.notes !== undefined) c.notes = i.notes;
if (i.installationMethod !== undefined) c.installationMethod = i.installationMethod;
if (i.ambientTempC !== undefined) c.ambientTempC = i.ambientTempC;
if (i.groupedCircuits !== undefined) c.groupedCircuits = i.groupedCircuits;

state.circuits = state.circuits.filter((c) => c.id !== action.input.id);
state.cabinetDevices = state.cabinetDevices.filter(
  (d) => d.circuitId !== action.input.id,
);
state.reports = state.reports.filter(
  (r) => r.circuitId !== action.input.id,
);
for (const u of state.units)
  for (const s of u.symbols)
    if (s.circuitId === action.input.id) s.circuitId = null;

if (
  action.input.circuitId &&
  !state.circuits.some((c) => c.id === action.input.circuitId)
)
  throw new UnknownCircuitError("Unknown circuit");
const u = state.units.find((x) => x.id === action.input.unitId);
if (!u) throw new UnknownUnitError("Unknown unit");
const s = u.symbols.find((x) => x.id === action.input.symbolId);
if (!s) throw new UnknownSymbolError("Unknown symbol");
s.circuitId = action.input.circuitId;

const r = action.input.route;
if (!state.circuits.some((c) => c.id === r.circuitId))
  throw new UnknownCircuitError("Unknown circuit");
if (!state.units.some((u) => u.id === r.unitId))
  throw new UnknownUnitError("Unknown unit");
if (!r.points || r.points.length < 2) return;
state.routes = state.routes ?? [];
if (state.routes.some((x) => x.id === r.id))
  throw new DuplicateIdError("Route id already exists");
state.routes.push({
  id: r.id,
  circuitId: r.circuitId,
  unitId: r.unitId,
  points: r.points.map((point) => ({ x: point.x, y: point.y })),
  reservePercent: r.reservePercent ?? 10,
});

const r = (state.routes ?? []).find((x) => x.id === action.input.id);
if (!r) return;
const i = action.input;
if (i.circuitId != null) {
  if (!state.circuits.some((c) => c.id === i.circuitId))
    throw new UnknownCircuitError("Unknown circuit");
  r.circuitId = i.circuitId;
}
if (i.unitId != null) {
  if (!state.units.some((u) => u.id === i.unitId))
    throw new UnknownUnitError("Unknown unit");
  r.unitId = i.unitId;
}
if (i.points != null && i.points.length >= 2)
  r.points = i.points.map((point) => ({ x: point.x, y: point.y }));
if (i.reservePercent !== undefined) r.reservePercent = i.reservePercent;

if (state.distributors.some((d) => d.id === action.input.distributor.id))
  throw new DuplicateIdError("Distribution board id already exists");
const d = action.input.distributor;
state.distributors.push({
  ...d,
  location: d.location ?? null,
});

const d = state.distributors.find((x) => x.id === action.input.id);
if (!d) throw new UnknownDistributorError("Unknown distribution board");
const i = action.input;
if (i.name != null) d.name = i.name;
if (i.rows !== undefined && i.rows !== null) d.rows = i.rows;
if (i.tePerRow !== undefined && i.tePerRow !== null)
  d.tePerRow = i.tePerRow;
if (i.reservePercent !== undefined && i.reservePercent !== null)
  d.reservePercent = i.reservePercent;
if (i.location !== undefined) d.location = i.location;

const d = state.distributors.find(
  (x) => x.id === action.input.distributorId,
);
if (!d) throw new UnknownDistributorError("Unknown distribution board");
state.cabinetDevices = [
  ...state.cabinetDevices.filter((x) => x.distributorId !== d.id),
  ...action.input.devices.map((x) => ({
    ...x,
    distributorId: d.id,
    article: x.article ?? null,
    circuitId: x.circuitId ?? null,
    phases: x.phases ?? null,
    price: x.price ?? null,
    row: x.row ?? null,
    startTe: x.startTe ?? null,
  })),
];

const seen = new Set();
for (const ga of action.input.addresses) {
  const key = `${ga.main}/${ga.middle}/${ga.sub}`;
  if (seen.has(key))
    throw new DuplicateGroupAddressError("Duplicate group address");
  seen.add(key);
}
state.groupAddresses = action.input.addresses.map((ga) => ({
  ...ga,
  description: ga.description ?? null,
  fixtureId: ga.fixtureId ?? null,
  functionKey: ga.functionKey ?? null,
}));

if (!state.circuits.some((c) => c.id === action.input.report.circuitId))
  throw new UnknownCircuitError("Unknown circuit");
const r = action.input.report;
state.reports = [
  ...state.reports.filter((item) => item.circuitId !== r.circuitId),
  {
    ...r,
    continuityOhm: r.continuityOhm ?? null,
    insulationMohm: r.insulationMohm ?? null,
    insulationTestVoltageV: r.insulationTestVoltageV ?? null,
    loopImpedanceOhm: r.loopImpedanceOhm ?? null,
    nextTestDue: r.nextTestDue ?? null,
    rcdTestCurrentMa: r.rcdTestCurrentMa ?? null,
    rotatingField: r.rotatingField ?? null,
    signature: r.signature ?? null,
    visualInspection: r.visualInspection ?? null,
    notes: r.notes ?? null,
    rcdTripMs: r.rcdTripMs ?? null,
    testedAt: r.testedAt ?? null,
    tester: r.tester ?? null,
  },
];
